if __name__ == '__main__':
    p, dictp = sys.argv[1], sys.argv[2]
    d = json.load(open(p))
    enable = set(w.strip().upper() for w in open(dictp))
    for c in d['categories']:
        extra = MORE.get(c['name'])
        if not extra:
            continue
        have = c['words'].split()
        allow = set((c.get('allow') or '').replace(',', ' ').upper().split())
        added, skipped = [], []
        for w in extra.split():
            w = w.upper()
            if w in have or w in added:
                continue
            if not (3 <= len(w) <= 8 and w.isalpha()):
                skipped.append(w); continue
            if not c.get('properNouns') and w not in enable and w not in allow:
                skipped.append(w); continue
            added.append(w)
        c['words'] = ' '.join(have + added)
        print(f"{c['name']:12s} {len(have)} + {len(added)} = {len(have) + len(added)}   skipped {len(skipped)}: {' '.join(skipped[:30])}")
    json.dump(d, open(p, 'w'), indent=2)
